var CLRS = ["#E40303", "#FF8C00", "#FFED00", "#008026", "#24408E", "#732982"]; // https://www.sexualdiversity.org/edu/flags/1051.php
var dia;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	describe("");
	pixelDensity(1);
	frameRate(30);
	noStroke();
	dia = max(width, height) / 3;
	camera(-dia, -dia, -dia*2, 0, 0, dia*CLRS.length/4, 0, 1, 0)
}

function draw() {
	background("lightblue");

	orbitControl();
	lights();
	pointLight(255, 25, 255, 0, -dia*2, - dia*CLRS.length/2); // clr, pos
	spotLight(color("white"), vec = createVector(0, dia*2, -dia*4*abs(sin(frameCount/60))), vec.mult(-1).normalize(), PI / 3); // clr, pos, dir
	// debugMode();

	// pride tori
	push()
	for (let i = 0; i < CLRS.length; i++) {
		fill(CLRS[i]);
		push()
		const yOff = sin(frameCount/60+i) * dia/4;
		translate(0, yOff, 0);
		torus(dia, dia/10, 64);
		pop()
		translate(0, 0, dia/2)
	}
	pop()

	// ground
	push();
	rotateX(-HALF_PI);
	fill("darkgreen"); // fill("rgb(42,67,12)");
	circle(0, 0, (CLRS.length+1) * dia);
	const th = dia / CLRS.length;
	if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && mouseButton != RIGHT) { // TODO: RIGHT not working
		for (let i = 0; i < CLRS.length * 4; i++) {
			fill((i+~~(frameCount/3))%2 ? "green" : "darkgreen");
			const ci = i + CLRS.length - ~~(frameCount/5) % CLRS.length;
			fill(CLRS[ci % CLRS.length]);
			torus(th * (i+1), th/2, 64);
		}
	}
	pop();
}
